import "../css/ProfileInfo.css";
import ProfileImage from "../../assets/images/profile_image_template.png";
import { useState } from "react";
export default function ProfileInfo(props) {
  const [isEditing, setIsEditing] = useState(false);
  function editProfile(event){
    debugger
  }
  function saveProfileInfo(event){
    event.preventDefault();
    event.stopPropagation();
    var username = document.querySelector('.userName').value;
    var usermail = document.querySelector('.userEmail').value;
    var password = document.querySelector('.userPassword').value;
    var confirmPassword = document.querySelector('.userConfirmPassword').value;
    if(password !== confirmPassword){
      alert("Passwords do not match");
      return;
    }
    var userInfo = {
        username: username,
        usermail: usermail,
        password: password
    };
    console.log(userInfo);
  }
  return (
    <div className="profileInfoContainer">
      {isEditing ? <span className="profilePreview">
        <span className="profileInfoHeader">
          <img
              src={ProfileImage}
              alt="Profile"
              className="profileInfoImage"
          />
          {props.userDetails && <h2>{props.userDetails.username}</h2>}
          <p className="profileEdit" onClick={editProfile}>Edit Profile</p>
          <i
            className="fa-solid fa-xmark close-icon"
            onClick={() => props.setIsProfileOpen(false)}
          ></i>
        </span>
        <span className="profileInfoDetails">
          <p>Email: {props.userDetails && props.userDetails.email}</p>
          <p>Phone: {props.userDetails && props.userDetails.phone}</p>
          <p>Address:</p>
          <span className="profileInfoAddress">
            <p>D.No : {props.userDetails && props.userDetails.address && props.userDetails.address.dno}</p>
            <p>Street: {props.userDetails && props.userDetails.address && props.userDetails.address.street}</p>
            <p>City: {props.userDetails && props.userDetails.address && props.userDetails.address.city}</p>
            <p>State: {props.userDetails && props.userDetails.address && props.userDetails.address.state}</p>
            <p>Zip: {props.userDetails && props.userDetails.address && props.userDetails.address.zip}</p>
          </span>
        </span>
      </span> : 
      <span className="profileEdit">
        <img
          src={ProfileImage}
          alt="Profile"
          className="profileInfoImage"
        />
        <form className="profileEditForm">
          <label className="profileEditLabel">
            Name
              <input type="text" name="username" className="userName" placeholder="Enter your username" />
          </label>
          <br />
          <label className="profileEditLabel">
              Email
              <input type="email" name="email" className="userEmail" placeholder="Enter your email" />
          </label>
          <label className="profileEditLabel">
              Phone
              <input type="tel" name="phone" className="userPhone" placeholder="Enter your phone number" />
          </label>
          <br />
          <button className="profileEditButton" type="submit" onClick={saveProfileInfo}>Save Changes</button>
        </form>
      </span>
      }
    </div>
  );
}
